      machoSegmentName: options.machoSegmentName,
      overwrite: options.overwrite,
      sentinelFuse: options.sentinelFuse,
    });
    logger.success("💉 Injection done!");
  } catch (err) {
    logger.error(err.message);
    process.exit(1);
  }
